from produire import produire
from format_lecon import paras,table,steps
parts=[
('L’{hypertrophie adénoamygdalienne} augmente le volume des végétations et des amygdales palatines. Elle peut rétrécir les voies aériennes de l’enfant. Sa signification dépend du retentissement, pas seulement de la taille.',paras('Les végétations occupent le rhinopharynx, derrière le nez ; les amygdales palatines bordent l’oropharynx. Leur développement est habituel dans l’enfance, mais une obstruction ou une inflammation chronique peut devenir pathologique.', 'Ronflement, respiration buccale et apnées sont des manifestations possibles. Toutes les grosses amygdales ne provoquent pas un syndrome d’apnées, et une obstruction sévère peut avoir plusieurs causes.')),
('Le {contexte pédiatrique est distinct de celui de l’adulte}. L’hypertrophie lymphoïde est une cause majeure d’apnées obstructives chez l’enfant. Obésité et anomalies craniofaciales peuvent s’y ajouter.',paras('La recommandation suisse situe le pic des apnées pédiatriques entre deux et huit ans dans les données qu’elle cite. Cette tranche n’exclut ni nourrisson ni adolescent.', 'Les enfants présentant un syndrome de Down ou d’autres anomalies des voies aériennes nécessitent une vigilance particulière. Une chirurgie sur les tissus lymphoïdes peut laisser persister une obstruction d’un autre niveau.')),
('Le {rétrécissement anatomique se combine au relâchement du sommeil}. L’espace disponible diminue dans le nez postérieur et le pharynx. La respiration devient plus coûteuse ou intermittente.',paras('Chez l’enfant, les événements obstructifs surviennent volontiers pendant le sommeil paradoxal. Le sommeil peut être fragmenté sans que la famille identifie des pauses nettes.', 'Les végétations peuvent aussi contribuer à une dysfonction de la trompe auditive. Une baisse d’audition, une respiration buccale et des difficultés de parole ou de déglutition doivent donc être recherchées.')),
('Les {alarmes sont respiratoires, nutritionnelles et développementales}. Cyanose ou détresse demandent une réponse urgente. Pauses importantes et défaut de croissance accélèrent l’évaluation.',paras('Un enfant avec effort marqué, terrain neuromusculaire ou anomalie craniofaciale doit être adressé à une équipe pédiatrique expérimentée. Ne pas attendre une somnolence comparable à celle d’un adulte.', 'Une masse atypique, un saignement ou une obstruction inhabituelle demandent un autre diagnostic. Chez l’adolescent, une lésion vasculaire du rhinopharynx ne doit pas être prélevée à l’aveugle.')),
('L’{anamnèse relie nuit, croissance et comportement}. Demander ronflement durable, pauses, positions inhabituelles et sommeil agité. Rechercher énurésie, irritabilité et difficultés scolaires.',paras('Une vidéo familiale peut aider à suspecter une obstruction, sans confirmer seule le diagnostic. Les parents décrivent parfois respiration bouche ouverte, fatigue, hyperactivité ou alimentation difficile.', 'Interroger sur infections, baisse d’audition, retard de langage, allergie, obésité et antécédents anesthésiques. Avant une chirurgie, rechercher une histoire personnelle ou familiale de saignement.')),
('L’{examen dépasse l’inspection des amygdales}. Évaluer respiration, croissance, bouche, palais, nez et oreilles. Rechercher une anomalie craniofaciale ou palatine.',paras('Les végétations ne se voient pas par la seule ouverture de la bouche. Une endoscopie souple, si tolérée et indiquée, précise leur volume et les autres obstacles.', 'L’otoscopie et l’évaluation auditive répondent aux symptômes associés. La présence d’une anomalie palatine modifie la discussion opératoire, notamment le risque de trouble de fermeture vélopharyngée.')),
('L’{approche syndromique distingue obstruction et simple hypertrophie}. L’évaluation doit aussi rechercher rhinite, malformation ou maladie générale. Plusieurs mécanismes peuvent se cumuler.',table(['Présentation','Orientation'],[['Ronflement avec respiration buccale et grosses amygdales.','Obstruction lymphoïde possible, retentissement nocturne à évaluer.'],['Rhinorrhée, prurit et éternuements.','Rhinite allergique associée ou alternative.'],['Baisse d’audition et otite séromuqueuse.','Dysfonction tubaire à documenter.'],['Obstruction persistante après chirurgie.','Tissu résiduel, récidive ou autre niveau d’obstruction.'] ])),
('Le {diagnostic associe anatomie et retentissement du sommeil}. La taille seule ne mesure pas les apnées. Les critères respiratoires sont pédiatriques.',paras('La SSSSC considère notamment un traitement chez les enfants avec IAH supérieur à cinq par heure, ou entre un et cinq avec symptômes, comorbidité ou facteur prédisposant. Ces critères ne doivent pas être importés dans un bilan adulte.', 'Un questionnaire et une vidéo orientent ; une étude du sommeil adaptée confirme le trouble quand elle est indiquée. Les moins de deux ans et les terrains complexes relèvent d’un centre expérimenté.')),
('Les {explorations sont adaptées à l’âge et au risque}. L’enregistrement nocturne s’organise avec l’équipe du sommeil pédiatrique. Les examens ORL répondent aux symptômes associés.',paras('Une oxymétrie seule ne suffit pas à exclure des apnées pédiatriques. Les pertes de capteurs et la coopération peuvent rendre une polygraphie peu fiable chez le petit enfant.', 'Tympanométrie et audiométrie sont utiles selon les signes auditifs. Une imagerie n’est pas systématique dans une hypertrophie banale ; une présentation atypique ou une malformation peut justifier des examens ciblés.')),
('L’{algorithme part du retentissement fonctionnel}. Identifier les formes urgentes puis documenter l’obstruction. Choisir une intervention et prévoir la réévaluation.',steps('Évaluer respiration, croissance et terrain à risque.', 'Examiner nez, amygdales, palais et oreilles ; rechercher les causes associées.', 'Organiser l’étude du sommeil selon indication et âge.', 'Discuter surveillance, traitement d’une cause associée ou chirurgie avec l’équipe pédiatrique.', 'Après traitement, vérifier sommeil, croissance, comportement et persistance éventuelle d’apnées.')),
('La {prise en charge suisse est pédiatrique et individualisée}. Une adénoamygdalectomie peut traiter une obstruction significative. La pression positive intervient dans certaines formes résiduelles ou non opérables.',paras('Le référentiel suisse retient la chirurgie en première intention dans les formes modérées à sévères avec hypertrophie amygdalienne. Les HUG décrivent une prise en charge ORL avec surveillance postopératoire adaptée. La décision tient compte de l’âge, de la sévérité et des comorbidités.', 'Une hypertrophie sans retentissement peut être surveillée. Une rhinite allergique associée se traite pour sa propre indication. Les corticoïdes nasaux proposés dans certaines hypertrophies ou apnées légères ne constituent pas automatiquement une indication AIPS autorisée pour ces troubles ; aucune dose hors indication n’est proposée ici.', 'Antibiotiques et corticoïdes systémiques ne sont pas un traitement de routine du volume des végétations. Les orthèses adultes ne doivent pas être transposées à l’enfant ; toute intervention orthodontique relève d’une évaluation spécialisée.')),
('Le {suivi recherche apnées résiduelles et complications opératoires}. Un saignement après chirurgie exige un avis urgent. La réapparition d’un ronflement doit être réévaluée.',paras('La recommandation suisse demande une réévaluation nocturne après chirurgie dans les formes préopératoires sévères ou si des symptômes persistent. Les HUG indiquent qu’un contrôle polygraphique à distance, au minimum six semaines après l’intervention, est souvent réalisé.', 'Contrôler aussi croissance, comportement et audition selon le tableau initial. Une récidive des végétations est possible ; une amélioration apparente ne justifie pas de perdre le suivi d’un enfant à risque.')),
('Le {point clé est le retentissement d’une obstruction nocturne}. Un enfant agité peut manquer de sommeil réparateur. Une opération ne dispense pas de vérifier le résultat.',paras('L’examen et le récit familial sont complémentaires d’une exploration adaptée. Les seuils, les dispositifs et le suivi restent pédiatriques.'))]
quiz=[('Les grosses amygdales suffisent-elles à prouver des apnées ?','Non.'),('Où se situent les végétations ?','Dans le rhinopharynx, derrière le nez.'),('L’enfant doit-il être somnolent pour être apnéique ?','Non, agitation et hyperactivité sont possibles.'),('La croissance doit-elle être examinée ?','Oui.'),('Une vidéo familiale confirme-t-elle seule le diagnostic ?','Non.'),('L’oxymétrie seule exclut-elle le trouble ?','Non.'),('Peut-on employer les seuils adultes chez l’enfant ?','Non.'),('Quel terrain impose une expertise particulière ?','Notamment jeune âge, syndrome de Down, anomalie craniofaciale ou maladie neuromusculaire.'),('Une baisse d’audition peut-elle être associée ?','Oui, par dysfonction tubaire notamment.'),('Tout ronflement impose-t-il une chirurgie ?','Non.'),('Les antibiotiques réduisent-ils de routine une hypertrophie simple ?','Non.'),('Un corticoïde nasal contre l’hypertrophie est-il automatiquement une indication AIPS ?','Non.'),('Que faire devant un saignement postopératoire ?','Obtenir une prise en charge urgente.'),('Des apnées peuvent-elles persister après chirurgie ?','Oui, d’où la réévaluation.')]
produire(3,parts,quiz,(1,2,3,21))
